175:   public findEntityAtLocation(
176:     filePath: string,
177:     line: number
178:   ): KnowledgeEntity | null {
179:     return (
180:       this.getEntitiesByFile(filePath)
181:         .filter(
182:           (entity) => entity.startLine <= line && entity.endLine >= line
183:         )
184:         .sort((left, right) => {
185:           const leftSpan = left.endLine - left.startLine;
186:           const rightSpan = right.endLine - right.startLine;
187:           return leftSpan - rightSpan || right.startLine - left.startLine;
188:         })[0] || null
189:     );
190:   }
