264: /** Parse the single supported grouped manifest shape. */
265: export function parseAgentGraphDocument(value: unknown): AgentGraphDocument {
266:   if (!isRecord(value)) {
267:     throw new Error('Generated graph root must be an object');
268:   }
269:   const generatedAt = requireIsoTimestamp(value.generatedAt, 'generatedAt');
270:   const scope = optionalScope(value.scope, 'scope');
271: 
272:   if (value.version !== 1) {
273:     throw new Error('Generated graph version must be 1');
274:   }
275:   if (!Array.isArray(value.groups) || value.groups.length === 0) {
276:     throw new Error('Generated graph groups must be a non-empty array');
277:   }
278: 
279:   const groupKeys = new Set<string>();
280:   const groupOrders = new Set<number>();
281:   const groups = value.groups.map((item, index) => {
282:     const group = parseGroup(item, index);
283:     if (groupKeys.has(group.key)) {
284:       throw new Error(`Duplicate generated graph group key: ${group.key}`);
285:     }
286:     if (groupOrders.has(group.order)) {
287:       throw new Error(`Duplicate generated graph group order: ${group.order}`);
288:     }
289:     groupKeys.add(group.key);
290:     groupOrders.add(group.order);
291:     return group;
292:   });
293: 
294:   const sortedGroups = [...groups].sort(
295:     (left, right) => left.order - right.order || left.name.localeCompare(right.name)
296:   );
297:   const frameworkGroups = sortedGroups.filter(
298:     (group) => group.kind === 'framework'
299:   );
300:   if (
301:     frameworkGroups.length !== 1 ||
302:     sortedGroups[0].kind !== 'framework' ||
303:     sortedGroups[0].key !== 'framework' ||
304:     sortedGroups[0].order !== 0
305:   ) {
306:     throw new Error(
307:       'Generated graph must start with exactly one framework group using key "framework" and order 0'
308:     );
309:   }
310: 
311:   return {
312:     version: 1,
313:     generatedAt,
314:     scope,
315:     groups: sortedGroups,
316:   };
317: }
