88: function deduplicate<T>(
89:   records: T[],
90:   identityAliases: (record: T) => string[],
91:   limit: number
92: ): T[] {
93:   const seen = new Set<string>();
94:   const uniqueResults: T[] = [];
95:   for (const record of records) {
96:     const aliases = identityAliases(record);
97:     if (aliases.some((alias) => seen.has(alias))) {
98:       continue;
99:     }
100:     aliases.forEach((alias) => seen.add(alias));
101:     uniqueResults.push(record);
102:     if (uniqueResults.length >= limit) {
103:       break;
104:     }
105:   }
106:   return uniqueResults;
107: }
