35: function createLogger(level: LogLevel): Logger {
36:   const levelWeight: Record<LogLevel, number> = {
37:     debug: 0,
38:     info: 1,
39:     error: 2
40:   };
41: 
42:   const threshold = levelWeight[level];
43: 
44:   const log =
45:     (msgLevel: LogLevel) =>
46:     (...args: unknown[]) => {
47:       if (levelWeight[msgLevel] < threshold) {
48:         return;
49:       }
50: 
51:       const prefix = `[${new Date().toISOString()}][${msgLevel.toUpperCase()}]`;
52:       console.error(prefix, ...args);
53:     };
54: 
55:   return {
56:     debug: log('debug'),
57:     info: log('info'),
58:     warn: log('info'),
59:     error: log('error')
60:   };
61: }
62: 
